// Saikuro Asyncify host shim (generated by `xtask`; edit
// `tools/xtask/assets/saikuro_asyncify.js` instead).

const NORMAL = 0;
const UNWINDING = 1;
const REWINDING = 2;

const RESUME_DELAY_MS = 0;

// The single instrumented module bound to this copy of the shim.
let binding = null;

export function asyncify_suspend() {
  if (binding === null) {
    throw new Error("saikuro asyncify: no wasm module is bound to this shim");
  }
  binding.suspend();
}

export function createAsyncify(entry) {
  if (
    entry === null ||
    typeof entry.call !== "function" ||
    typeof entry.rewind !== "function"
  ) {
    throw new Error(
      "saikuro asyncify: entry must provide call() and rewind() functions",
    );
  }
  if (binding !== null) {
    throw new Error(
      "saikuro asyncify: this shim copy is already bound to a wasm module; " +
        "each instrumented package needs its own shim file"
    );
  }

  let wasm = null;
  let data = 0;
  let state = NORMAL;
  let suspendedThisCall = false;
  let resumeScheduled = false;
  let pending = null;

  function suspend() {
    if (state === REWINDING) {
      // The rewind re-executed the suspend import, so the stack continues from
      // just after the suspend point. Close the rewind before returning to wasm.
      state = NORMAL;
      wasm.asyncify_stop_rewind();
    } else {
      // Fresh suspend point: freeze the stack and unwind out to JS.
      state = UNWINDING;
      suspendedThisCall = true;
      wasm.asyncify_start_unwind(data);
    }
  }

  // Every entry invocation may return with the stack frozen.
  function afterEntry() {
    if (state === UNWINDING) {
      state = NORMAL;
      wasm.asyncify_stop_unwind();
    }
  }

  function scheduleResume() {
    if (resumeScheduled) return;
    resumeScheduled = true;
    setTimeout(runResume, RESUME_DELAY_MS);
  }

  function runResume() {
    resumeScheduled = false;
    state = REWINDING;
    wasm.asyncify_start_rewind(data);
    suspendedThisCall = false;
    // Rewind through `entry.rewind`, which jumps straight into the raw wasm
    // export. The frozen frame restores its own arguments, so the rewind needs
    // none.
    let result;
    try {
      result = entry.rewind();
    } catch (err) {
      // The resumed body threw, so nothing will resolve or suspend the captured
      // promise again. Fail it here
      state = NORMAL;
      const failed = pending;
      pending = null;
      if (failed) failed.reject(err);
      return;
    }
    afterEntry();
    if (suspendedThisCall) {
      scheduleResume();
      return;
    }
    // Ran to completion without suspending again: this is the real result.
    const settled = pending;
    pending = null;
    if (settled) settled.resolve(result);
  }

  function callSync(op) {
    if (wasm === null) {
      return Promise.reject(new Error("saikuro asyncify: module not initialized"));
    }
    if (pending !== null) {
      return Promise.reject(new Error("saikuro asyncify: reentrant callSync"));
    }
    let resolve;
    let reject;
    const promise = new Promise((res, rej) => {
      resolve = res;
      reject = rej;
    });
    pending = { resolve, reject };

    state = NORMAL;
    suspendedThisCall = false;
    let immediate;
    try {
      immediate = entry.call(op);
    } catch (err) {
      pending = null;
      return Promise.reject(err);
    }
    afterEntry();

    if (suspendedThisCall) {
      // Expected path: the future is not ready yet and suspended.
      scheduleResume();
      return promise;
    }
    // Completed without suspending, e.g. the future was already ready.
    pending = null;
    return Promise.resolve(immediate);
  }

  function attach(instance) {
    if (wasm !== null) return instance;
    for (const name of [
      "data_ptr",
      "asyncify_start_unwind",
      "asyncify_stop_unwind",
      "asyncify_start_rewind",
      "asyncify_stop_rewind",
    ]) {
      if (typeof instance[name] !== "function") {
        throw new Error(
          `saikuro asyncify: wasm export "${name}" is missing; ` +
            "the module was not instrumented with `wasm-opt --asyncify`"
        );
      }
    }
    wasm = instance;
    data = instance.data_ptr();
    binding = { suspend };
    return instance;
  }

  return { callSync, attach };
}
